void cvkCmdBeginColorRendering(VkCommandBuffer commandBuffer, VkImageView imageView, VkImageLayout imageLayout, VkAttachmentLoadOp loadOp, VkAttachmentStoreOp storeOp, VkClearValue clearValue, const void* pNext, VkRenderingFlags flags, VkRect2D renderArea, uint32_t layerCount, uint32_t viewMask, const void* pColorAttachmentNext);

