void cvkCreateSingleAttachmentFramebuffer(VkDevice device, const void* pFramebufferNext, VkFramebufferCreateFlags flags, VkRenderPass renderPass, uint32_t width, uint32_t height, uint32_t layers, VkImageView attachment, const VkAllocationCallbacks* pAllocator, VkFramebuffer* pFramebuffer);

