/*************************************************************************************************/
/**
 * \brief Creates a host-visible shader binding table buffer.
 *
 * \param[in]  physicalDevice          The handle to the device to query
 * \param[in]  device                  The logical device that creates the buffer object
 * \param[in]  pBufferNext             Optional extension chain attached to VkBufferCreateInfo, or NULL
 * \param[in]  flags                   A bitmask of VkBufferCreateFlagBits specifying additional parameters of the buffer
 * \param[in]  size                    The size in bytes of the buffer to be created
 * \param[in]  sharingMode             A VkSharingMode value specifying the sharing mode of the buffer when it will be accessed by multiple queue families
 * \param[in]  queueFamilyIndexCount   The number of entries in the pQueueFamilyIndices array
 * \param[in]  pQueueFamilyIndices     A pointer to an array of queue families that will access this buffer
 * \param[in]  pMemoryNext             Optional extension chain appended after the VkMemoryAllocateFlagsInfo in VkMemoryAllocateInfo, or NULL
 * \param[in]  pAllocator              Optional allocation callbacks, or NULL
 * \param[out] pBuffer                 A pointer to a VkBuffer handle in which the resulting buffer object is returned
 * \param[out] pMemory                 A pointer to a VkDeviceMemory handle in which information about the allocated memory is returned
 *
 * \retval     None
 */
void cvkSetupShaderBindingTableBuffer(VkPhysicalDevice physicalDevice, VkDevice device, const void* pBufferNext, VkBufferCreateFlags flags, VkDeviceSize size, VkSharingMode sharingMode, uint32_t queueFamilyIndexCount, const uint32_t* pQueueFamilyIndices, const void* pMemoryNext, const VkAllocationCallbacks* pAllocator, VkBuffer* pBuffer, VkDeviceMemory* pMemory);

/*************************************************************************************************/
/**
 * \brief Creates a host-visible buffer for acceleration structure build inputs (vertices, indices, transforms, AABBs, instances).
 *
 * \param[in]  physicalDevice          The handle to the device to query
 * \param[in]  device                  The logical device that creates the buffer object
 * \param[in]  pBufferNext             Optional extension chain attached to VkBufferCreateInfo, or NULL
 * \param[in]  flags                   A bitmask of VkBufferCreateFlagBits specifying additional parameters of the buffer
 * \param[in]  size                    The size in bytes of the buffer to be created
 * \param[in]  sharingMode             A VkSharingMode value specifying the sharing mode of the buffer when it will be accessed by multiple queue families
 * \param[in]  queueFamilyIndexCount   The number of entries in the pQueueFamilyIndices array
 * \param[in]  pQueueFamilyIndices     A pointer to an array of queue families that will access this buffer
 * \param[in]  pMemoryNext             Optional extension chain appended after the VkMemoryAllocateFlagsInfo in VkMemoryAllocateInfo, or NULL
 * \param[in]  pAllocator              Optional allocation callbacks, or NULL
 * \param[out] pBuffer                 A pointer to a VkBuffer handle in which the resulting buffer object is returned
 * \param[out] pMemory                 A pointer to a VkDeviceMemory handle in which information about the allocated memory is returned
 *
 * \retval     None
 */
void cvkSetupAccelerationStructureBuildInputBuffer(VkPhysicalDevice physicalDevice, VkDevice device, const void* pBufferNext, VkBufferCreateFlags flags, VkDeviceSize size, VkSharingMode sharingMode, uint32_t queueFamilyIndexCount, const uint32_t* pQueueFamilyIndices, const void* pMemoryNext, const VkAllocationCallbacks* pAllocator, VkBuffer* pBuffer, VkDeviceMemory* pMemory);

/*************************************************************************************************/
/**
 * \brief Creates a bottom-level acceleration structure over a buffer range.
 *
 * \param[in]  device                       The logical device that creates the acceleration structure object
 * \param[in]  pAccelerationStructureNext   Optional extension chain attached to VkAccelerationStructureCreateInfoKHR, or NULL
 * \param[in]  createFlags                  A bitmask of VkAccelerationStructureCreateFlagBitsKHR specifying additional creation parameters of the acceleration structure
 * \param[in]  buffer                       The buffer on which the acceleration structure will be stored
 * \param[in]  offset                       An offset in bytes from the base address of the buffer at which the acceleration structure will be stored, and must be a multiple of 256
 * \param[in]  size                         The size required for the acceleration structure
 * \param[in]  pAllocator                   Optional allocation callbacks, or NULL
 * \param[out] pAccelerationStructure       A pointer to a VkAccelerationStructureKHR handle in which the resulting acceleration structure object is returned
 *
 * \retval     None
 */
void cvkCreateBottomLevelAccelerationStructure(VkDevice device, const void* pAccelerationStructureNext, VkAccelerationStructureCreateFlagsKHR createFlags, VkBuffer buffer, VkDeviceSize offset, VkDeviceSize size, const VkAllocationCallbacks* pAllocator, VkAccelerationStructureKHR* pAccelerationStructure);

/*************************************************************************************************/
/**
 * \brief Creates a top-level acceleration structure over a buffer range.
 *
 * \param[in]  device                       The logical device that creates the acceleration structure object
 * \param[in]  pAccelerationStructureNext   Optional extension chain attached to VkAccelerationStructureCreateInfoKHR, or NULL
 * \param[in]  createFlags                  A bitmask of VkAccelerationStructureCreateFlagBitsKHR specifying additional creation parameters of the acceleration structure
 * \param[in]  buffer                       The buffer on which the acceleration structure will be stored
 * \param[in]  offset                       An offset in bytes from the base address of the buffer at which the acceleration structure will be stored, and must be a multiple of 256
 * \param[in]  size                         The size required for the acceleration structure
 * \param[in]  pAllocator                   Optional allocation callbacks, or NULL
 * \param[out] pAccelerationStructure       A pointer to a VkAccelerationStructureKHR handle in which the resulting acceleration structure object is returned
 *
 * \retval     None
 */
void cvkCreateTopLevelAccelerationStructure(VkDevice device, const void* pAccelerationStructureNext, VkAccelerationStructureCreateFlagsKHR createFlags, VkBuffer buffer, VkDeviceSize offset, VkDeviceSize size, const VkAllocationCallbacks* pAllocator, VkAccelerationStructureKHR* pAccelerationStructure);

/*************************************************************************************************/
/**
 * \brief Initializes a geometry of type VK_GEOMETRY_TYPE_TRIANGLES_KHR.
 *
 * \param[out] pInfo       Receives the initialized VkAccelerationStructureGeometryKHR
 * \param[in]  pNext       Optional extension chain attached to VkAccelerationStructureGeometryKHR, or NULL
 * \param[in]  triangles   Triangle geometry data, for VK_GEOMETRY_TYPE_TRIANGLES_KHR geometries
 * \param[in]  flags       A bitmask of VkGeometryFlagBitsKHR values describing additional properties of how the geometry should be built
 *
 * \retval     None
 */
void cvkInitTrianglesAccelerationStructureGeometry(VkAccelerationStructureGeometryKHR* pInfo, const void* pNext, VkAccelerationStructureGeometryTrianglesDataKHR triangles, VkGeometryFlagsKHR flags);

/*************************************************************************************************/
/**
 * \brief Initializes a geometry of type VK_GEOMETRY_TYPE_AABBS_KHR.
 *
 * \param[out] pInfo   Receives the initialized VkAccelerationStructureGeometryKHR
 * \param[in]  pNext   Optional extension chain attached to VkAccelerationStructureGeometryKHR, or NULL
 * \param[in]  aabbs   Axis-aligned bounding box geometry data, for VK_GEOMETRY_TYPE_AABBS_KHR geometries
 * \param[in]  flags   A bitmask of VkGeometryFlagBitsKHR values describing additional properties of how the geometry should be built
 *
 * \retval     None
 */
void cvkInitAabbsAccelerationStructureGeometry(VkAccelerationStructureGeometryKHR* pInfo, const void* pNext, VkAccelerationStructureGeometryAabbsDataKHR aabbs, VkGeometryFlagsKHR flags);

/*************************************************************************************************/
/**
 * \brief Initializes a geometry of type VK_GEOMETRY_TYPE_INSTANCES_KHR.
 *
 * \param[out] pInfo       Receives the initialized VkAccelerationStructureGeometryKHR
 * \param[in]  pNext       Optional extension chain attached to VkAccelerationStructureGeometryKHR, or NULL
 * \param[in]  instances   Instance geometry data, for VK_GEOMETRY_TYPE_INSTANCES_KHR geometries
 * \param[in]  flags       A bitmask of VkGeometryFlagBitsKHR values describing additional properties of how the geometry should be built
 *
 * \retval     None
 */
void cvkInitInstancesAccelerationStructureGeometry(VkAccelerationStructureGeometryKHR* pInfo, const void* pNext, VkAccelerationStructureGeometryInstancesDataKHR instances, VkGeometryFlagsKHR flags);

/*************************************************************************************************/
/**
 * \brief Initializes triangle geometry data from device addresses; a zero index address means non-indexed, a zero transform address no transform.
 *
 * \param[out] pInfo                    Receives the initialized VkAccelerationStructureGeometryTrianglesDataKHR
 * \param[in]  pNext                    Optional extension chain attached to VkAccelerationStructureGeometryTrianglesDataKHR, or NULL
 * \param[in]  vertexFormat             The VkFormat of each vertex element
 * \param[in]  vertexStride             The stride in bytes between each vertex
 * \param[in]  maxVertex                The number of vertices in vertexData minus one
 * \param[in]  indexType                The VkIndexType of each index element
 * \param[in]  vertexDeviceAddress      Device address of the vertices
 * \param[in]  indexDeviceAddress       Device address of the indices, or 0
 * \param[in]  transformDeviceAddress   Device address of the VkTransformMatrixKHR, or 0
 *
 * \retval     None
 */
void cvkInitDeviceAccelerationStructureGeometryTrianglesData(VkAccelerationStructureGeometryTrianglesDataKHR* pInfo, const void* pNext, VkFormat vertexFormat, VkDeviceSize vertexStride, uint32_t maxVertex, VkIndexType indexType, VkDeviceAddress vertexDeviceAddress, VkDeviceAddress indexDeviceAddress, VkDeviceAddress transformDeviceAddress);

/*************************************************************************************************/
/**
 * \brief Initializes instance geometry data from the device address of a tightly packed VkAccelerationStructureInstanceKHR array.
 *
 * \param[out] pInfo                    Receives the initialized VkAccelerationStructureGeometryInstancesDataKHR
 * \param[in]  pNext                    Optional extension chain attached to VkAccelerationStructureGeometryInstancesDataKHR, or NULL
 * \param[in]  instancesDeviceAddress   Device address of the instances
 *
 * \retval     None
 */
void cvkInitDeviceAccelerationStructureGeometryInstancesData(VkAccelerationStructureGeometryInstancesDataKHR* pInfo, const void* pNext, VkDeviceAddress instancesDeviceAddress);

/*************************************************************************************************/
/**
 * \brief Initializes AABB geometry data from a device address.
 *
 * \param[out] pInfo                Receives the initialized VkAccelerationStructureGeometryAabbsDataKHR
 * \param[in]  pNext                Optional extension chain attached to VkAccelerationStructureGeometryAabbsDataKHR, or NULL
 * \param[in]  stride               The stride in bytes between each entry in data
 * \param[in]  aabbsDeviceAddress   Device address of the VkAabbPositionsKHR array
 *
 * \retval     None
 */
void cvkInitDeviceAccelerationStructureGeometryAabbsData(VkAccelerationStructureGeometryAabbsDataKHR* pInfo, const void* pNext, VkDeviceSize stride, VkDeviceAddress aabbsDeviceAddress);

/*************************************************************************************************/
/**
 * \brief Records one acceleration structure build.
 *
 * \param[in] commandBuffer              The command buffer into which the command will be recorded
 * \param[in] pNext                      Optional extension chain attached to VkAccelerationStructureBuildGeometryInfoKHR, or NULL
 * \param[in] type                       A VkAccelerationStructureTypeKHR value specifying the type of acceleration structure being built
 * \param[in] flags                      A bitmask of VkBuildAccelerationStructureFlagBitsKHR specifying additional parameters of the acceleration structure
 * \param[in] mode                       A VkBuildAccelerationStructureModeKHR value specifying the type of operation to perform
 * \param[in] srcAccelerationStructure   Existing acceleration structure to update dstAccelerationStructure from when mode is VK_BUILD_ACCELERATION_STRUCTURE_MODE_UPDATE_KHR
 * \param[in] dstAccelerationStructure   The target acceleration structure for the build
 * \param[in] geometryCount              Specifies the number of geometries that will be built into dstAccelerationStructure
 * \param[in] pGeometries                A pointer to an array of VkAccelerationStructureGeometryKHR structures
 * \param[in] ppGeometries               A pointer to an array of pointers to VkAccelerationStructureGeometryKHR structures
 * \param[in] scratchData                The device or host address of memory that will be used as scratch memory for the build
 * \param[in] pBuildRangeInfos           One build range per geometry
 *
 * \retval    None
 */
void cvkCmdBuildAccelerationStructure(VkCommandBuffer commandBuffer, const void* pNext, VkAccelerationStructureTypeKHR type, VkBuildAccelerationStructureFlagsKHR flags, VkBuildAccelerationStructureModeKHR mode, VkAccelerationStructureKHR srcAccelerationStructure, VkAccelerationStructureKHR dstAccelerationStructure, uint32_t geometryCount, const VkAccelerationStructureGeometryKHR* pGeometries, const VkAccelerationStructureGeometryKHR* const* ppGeometries, VkDeviceOrHostAddressKHR scratchData, const VkAccelerationStructureBuildRangeInfoKHR* pBuildRangeInfos);

/*************************************************************************************************/
/**
 * \brief Records a full build of an acceleration structure from device-address geometries into device scratch memory.
 *
 * \param[in] commandBuffer              The command buffer into which the command will be recorded
 * \param[in] pNext                      Optional extension chain attached to VkAccelerationStructureBuildGeometryInfoKHR, or NULL
 * \param[in] type                       A VkAccelerationStructureTypeKHR value specifying the type of acceleration structure being built
 * \param[in] flags                      A bitmask of VkBuildAccelerationStructureFlagBitsKHR specifying additional parameters of the acceleration structure
 * \param[in] dstAccelerationStructure   The target acceleration structure for the build
 * \param[in] geometryCount              Specifies the number of geometries that will be built into dstAccelerationStructure
 * \param[in] pGeometries                A pointer to an array of VkAccelerationStructureGeometryKHR structures
 * \param[in] pBuildRangeInfos           One build range per geometry
 * \param[in] scratchDeviceAddress       Aligned scratch device address, as cvkSetupAccelerationStructure returns
 *
 * \retval    None
 */
void cvkCmdBuildDeviceAccelerationStructure(VkCommandBuffer commandBuffer, const void* pNext, VkAccelerationStructureTypeKHR type, VkBuildAccelerationStructureFlagsKHR flags, VkAccelerationStructureKHR dstAccelerationStructure, uint32_t geometryCount, const VkAccelerationStructureGeometryKHR* pGeometries, const VkAccelerationStructureBuildRangeInfoKHR* pBuildRangeInfos, VkDeviceAddress scratchDeviceAddress);

/*************************************************************************************************/
/**
 * \brief Records a full bottom-level build.
 *
 * \param[in] commandBuffer              The command buffer into which the command will be recorded
 * \param[in] pNext                      Optional extension chain attached to VkAccelerationStructureBuildGeometryInfoKHR, or NULL
 * \param[in] flags                      A bitmask of VkBuildAccelerationStructureFlagBitsKHR specifying additional parameters of the acceleration structure
 * \param[in] dstAccelerationStructure   The target acceleration structure for the build
 * \param[in] geometryCount              Specifies the number of geometries that will be built into dstAccelerationStructure
 * \param[in] pGeometries                A pointer to an array of VkAccelerationStructureGeometryKHR structures
 * \param[in] pBuildRangeInfos           One build range per geometry
 * \param[in] scratchDeviceAddress       Aligned scratch device address, as cvkSetupAccelerationStructure returns
 *
 * \retval    None
 */
void cvkCmdBuildDeviceBottomLevelAccelerationStructure(VkCommandBuffer commandBuffer, const void* pNext, VkBuildAccelerationStructureFlagsKHR flags, VkAccelerationStructureKHR dstAccelerationStructure, uint32_t geometryCount, const VkAccelerationStructureGeometryKHR* pGeometries, const VkAccelerationStructureBuildRangeInfoKHR* pBuildRangeInfos, VkDeviceAddress scratchDeviceAddress);

/*************************************************************************************************/
/**
 * \brief Records a full top-level build.
 *
 * \param[in] commandBuffer              The command buffer into which the command will be recorded
 * \param[in] pNext                      Optional extension chain attached to VkAccelerationStructureBuildGeometryInfoKHR, or NULL
 * \param[in] flags                      A bitmask of VkBuildAccelerationStructureFlagBitsKHR specifying additional parameters of the acceleration structure
 * \param[in] dstAccelerationStructure   The target acceleration structure for the build
 * \param[in] geometryCount              Specifies the number of geometries that will be built into dstAccelerationStructure
 * \param[in] pGeometries                A pointer to an array of VkAccelerationStructureGeometryKHR structures
 * \param[in] pBuildRangeInfos           One build range per geometry
 * \param[in] scratchDeviceAddress       Aligned scratch device address, as cvkSetupAccelerationStructure returns
 *
 * \retval    None
 */
void cvkCmdBuildDeviceTopLevelAccelerationStructure(VkCommandBuffer commandBuffer, const void* pNext, VkBuildAccelerationStructureFlagsKHR flags, VkAccelerationStructureKHR dstAccelerationStructure, uint32_t geometryCount, const VkAccelerationStructureGeometryKHR* pGeometries, const VkAccelerationStructureBuildRangeInfoKHR* pBuildRangeInfos, VkDeviceAddress scratchDeviceAddress);

/*************************************************************************************************/
/**
 * \brief Records the barrier between an acceleration structure build and a subsequent build reading it or a ray tracing shader using it.
 *
 * \param[in] commandBuffer   The command buffer into which the command is recorded
 *
 * \retval    None
 */
void cvkCmdAccelerationStructureBuildBarrier(VkCommandBuffer commandBuffer);

/*************************************************************************************************/
/**
 * \brief Writes one acceleration structure descriptor.
 *
 * \param[in] device                  The logical device that updates the descriptor sets
 * \param[in] pNext                   Optional extension chain attached to VkWriteDescriptorSetAccelerationStructureKHR, or NULL
 * \param[in] dstSet                  The destination descriptor set to update
 * \param[in] dstBinding              Binding number to update within dstSet
 * \param[in] dstArrayElement         First array element to update in dstBinding
 * \param[in] accelerationStructure   The acceleration structure to write
 *
 * \retval    None
 */
void cvkUpdateAccelerationStructureDescriptorSet(VkDevice device, const void* pNext, VkDescriptorSet dstSet, uint32_t dstBinding, uint32_t dstArrayElement, VkAccelerationStructureKHR accelerationStructure);

/*************************************************************************************************/
/**
 * \brief Binds a ray tracing pipeline.
 *
 * \param[in] commandBuffer   The command buffer that the pipeline will be bound to
 * \param[in] pipeline        The pipeline to be bound
 *
 * \retval    None
 */
void cvkCmdBindRayTracingPipeline(VkCommandBuffer commandBuffer, VkPipeline pipeline);

/*************************************************************************************************/
/**
 * \brief Binds descriptor sets to the ray tracing bind point.
 *
 * \param[in] commandBuffer        The command buffer that the descriptor sets will be bound to
 * \param[in] layout               A VkPipelineLayout object used to program the bindings
 * \param[in] firstSet             The set number of the first descriptor set to be bound
 * \param[in] descriptorSetCount   The number of elements in the pDescriptorSets array
 * \param[in] pDescriptorSets      A pointer to an array of handles to VkDescriptorSet objects describing the descriptor sets to bind to
 * \param[in] dynamicOffsetCount   The number of dynamic offsets in the pDynamicOffsets array
 * \param[in] pDynamicOffsets      A pointer to an array of uint32_t values specifying dynamic offsets
 *
 * \retval    None
 */
void cvkCmdBindRayTracingDescriptorSets(VkCommandBuffer commandBuffer, VkPipelineLayout layout, uint32_t firstSet, uint32_t descriptorSetCount, const VkDescriptorSet* pDescriptorSets, uint32_t dynamicOffsetCount, const uint32_t* pDynamicOffsets);

/*************************************************************************************************/
/**
 * \brief Pushes constants for every ray tracing stage.
 *
 * \param[in] commandBuffer   The command buffer in which the push constant update will be recorded
 * \param[in] layout          The pipeline layout used to program the push constant updates
 * \param[in] offset          The start offset of the push constant range to update, in units of bytes
 * \param[in] size            The size of the push constant range to update, in units of bytes
 * \param[in] pValues         A pointer to an array of size bytes containing the new push constant values
 *
 * \retval    None
 */
void cvkCmdPushRayTracingConstants(VkCommandBuffer commandBuffer, VkPipelineLayout layout, uint32_t offset, uint32_t size, const void* pValues);

/*************************************************************************************************/
/**
 * \brief Creates a pipeline layout for every ray tracing stage with at most one push constant range.
 *
 * \param[in]  device                The logical device that creates the pipeline layout
 * \param[in]  pPipelineLayoutNext   Optional extension chain attached to VkPipelineLayoutCreateInfo, or NULL
 * \param[in]  flags                 A bitmask of VkPipelineLayoutCreateFlagBits specifying options for pipeline layout creation
 * \param[in]  setLayoutCount        The number of descriptor sets included in the pipeline layout
 * \param[in]  pSetLayouts           Array of setLayoutCount descriptor set layouts; element i is the layout of set number i
 * \param[in]  pushConstantOffset    Byte offset of the push constant range; a multiple of 4
 * \param[in]  pushConstantSize      Size of the push constant range, zero for none
 * \param[in]  pAllocator            Optional allocation callbacks, or NULL
 * \param[out] pPipelineLayout       A pointer to a VkPipelineLayout handle in which the resulting pipeline layout object is returned
 *
 * \retval     None
 */
void cvkCreateRayTracingPipelineLayout(VkDevice device, const void* pPipelineLayoutNext, VkPipelineLayoutCreateFlags flags, uint32_t setLayoutCount, const VkDescriptorSetLayout* pSetLayouts, uint32_t pushConstantOffset, uint32_t pushConstantSize, const VkAllocationCallbacks* pAllocator, VkPipelineLayout* pPipelineLayout);

/*************************************************************************************************/
/**
 * \brief Initializes a general shader group (raygen, miss, or callable) of one stage.
 *
 * \param[out] pInfo           Receives the initialized VkRayTracingShaderGroupCreateInfoKHR
 * \param[in]  pNext           Optional extension chain attached to VkRayTracingShaderGroupCreateInfoKHR, or NULL
 * \param[in]  generalShader   The index of the ray generation, miss, or callable shader from VkRayTracingPipelineCreateInfoKHR::pStages in the group if the shader group has type of VK_RAY_TRACING_SHADER_GROUP_TYPE_GENERAL_KHR, and VK_SHADER_UNUSED_KHR otherwise
 *
 * \retval     None
 */
void cvkInitGeneralRayTracingShaderGroupCreateInfo(VkRayTracingShaderGroupCreateInfoKHR* pInfo, const void* pNext, uint32_t generalShader);

/*************************************************************************************************/
/**
 * \brief Initializes a triangles hit group of a closest hit and an optional any hit stage.
 *
 * \param[out] pInfo              Receives the initialized VkRayTracingShaderGroupCreateInfoKHR
 * \param[in]  pNext              Optional extension chain attached to VkRayTracingShaderGroupCreateInfoKHR, or NULL
 * \param[in]  closestHitShader   The optional index of the closest hit shader from VkRayTracingPipelineCreateInfoKHR::pStages in the group if the shader group has type of VK_RAY_TRACING_SHADER_GROUP_TYPE_TRIANGLES_HIT_GROUP_KHR or VK_RAY_TRACING_SHADER_GROUP_TYPE_PROCEDURAL_HIT_GROUP_KHR, and VK_SHADER_UNUSED_KHR otherwise
 * \param[in]  anyHitShader       The optional index of the any-hit shader from VkRayTracingPipelineCreateInfoKHR::pStages in the group if the shader group has type of VK_RAY_TRACING_SHADER_GROUP_TYPE_TRIANGLES_HIT_GROUP_KHR or VK_RAY_TRACING_SHADER_GROUP_TYPE_PROCEDURAL_HIT_GROUP_KHR, and VK_SHADER_UNUSED_KHR otherwise
 *
 * \retval     None
 */
void cvkInitTrianglesHitRayTracingShaderGroupCreateInfo(VkRayTracingShaderGroupCreateInfoKHR* pInfo, const void* pNext, uint32_t closestHitShader, uint32_t anyHitShader);

/*************************************************************************************************/
/**
 * \brief Initializes a procedural hit group of an intersection, a closest hit, and an optional any hit stage.
 *
 * \param[out] pInfo                Receives the initialized VkRayTracingShaderGroupCreateInfoKHR
 * \param[in]  pNext                Optional extension chain attached to VkRayTracingShaderGroupCreateInfoKHR, or NULL
 * \param[in]  closestHitShader     The optional index of the closest hit shader from VkRayTracingPipelineCreateInfoKHR::pStages in the group if the shader group has type of VK_RAY_TRACING_SHADER_GROUP_TYPE_TRIANGLES_HIT_GROUP_KHR or VK_RAY_TRACING_SHADER_GROUP_TYPE_PROCEDURAL_HIT_GROUP_KHR, and VK_SHADER_UNUSED_KHR otherwise
 * \param[in]  anyHitShader         The optional index of the any-hit shader from VkRayTracingPipelineCreateInfoKHR::pStages in the group if the shader group has type of VK_RAY_TRACING_SHADER_GROUP_TYPE_TRIANGLES_HIT_GROUP_KHR or VK_RAY_TRACING_SHADER_GROUP_TYPE_PROCEDURAL_HIT_GROUP_KHR, and VK_SHADER_UNUSED_KHR otherwise
 * \param[in]  intersectionShader   The index of the intersection shader from VkRayTracingPipelineCreateInfoKHR::pStages in the group if the shader group has type of VK_RAY_TRACING_SHADER_GROUP_TYPE_PROCEDURAL_HIT_GROUP_KHR, and VK_SHADER_UNUSED_KHR otherwise
 *
 * \retval     None
 */
void cvkInitProceduralHitRayTracingShaderGroupCreateInfo(VkRayTracingShaderGroupCreateInfoKHR* pInfo, const void* pNext, uint32_t closestHitShader, uint32_t anyHitShader, uint32_t intersectionShader);

/*************************************************************************************************/
/**
 * \brief Creates raygen, miss, and closest hit shader modules, three shader groups (general, general, triangles hit), a ray tracing pipeline layout, and a ray tracing pipeline; the groups are in shader binding table order.
 *
 * \param[in]  device                          The logical device that creates the shader module
 * \param[in]  pPipelineLayoutNext             Optional extension chain attached to VkPipelineLayoutCreateInfo, or NULL
 * \param[in]  setLayoutCount                  The number of descriptor sets included in the pipeline layout
 * \param[in]  pSetLayouts                     Array of setLayoutCount descriptor set layouts; element i is the layout of set number i
 * \param[in]  pushConstantOffset              Byte offset of the push constant range; a multiple of 4
 * \param[in]  pushConstantSize                Size of the push constant range, zero for none
 * \param[in]  pipelineCache                   Either VK_NULL_HANDLE, indicating that pipeline caching is disabled, or to enable caching, the handle of a valid VkPipelineCache object
 * \param[in]  pPipelineNext                   Optional extension chain attached to VkRayTracingPipelineCreateInfoKHR, or NULL
 * \param[in]  flags                           A bitmask of VkPipelineCreateFlagBits specifying how the pipeline will be generated
 * \param[in]  maxPipelineRayRecursionDepth    The maximum recursion depth of shaders executed by this pipeline
 * \param[in]  shaderModuleFlags               VkShaderModuleCreateInfo::flags of every module
 * \param[in]  pipelineLayoutFlags             A bitmask of VkPipelineLayoutCreateFlagBits specifying options for pipeline layout creation
 * \param[in]  stageFlags                      VkPipelineShaderStageCreateInfo::flags of every stage
 * \param[in]  pRaygenShaderModuleNext         Optional extension chain for the raygen VkShaderModuleCreateInfo, or NULL
 * \param[in]  raygenCodeSize                  Size in bytes of the raygen shader code
 * \param[in]  pRaygenCode                     Raygen shader SPIR-V code
 * \param[in]  pRaygenStageNext                Optional extension chain for the raygen VkPipelineShaderStageCreateInfo, or NULL
 * \param[in]  pRaygenEntryPoint               Entry point name of the raygen shader
 * \param[in]  pRaygenSpecializationInfo       Specialization of the raygen shader, or NULL
 * \param[in]  pMissShaderModuleNext           Optional extension chain for the miss VkShaderModuleCreateInfo, or NULL
 * \param[in]  missCodeSize                    Size in bytes of the miss shader code
 * \param[in]  pMissCode                       Miss shader SPIR-V code
 * \param[in]  pMissStageNext                  Optional extension chain for the miss VkPipelineShaderStageCreateInfo, or NULL
 * \param[in]  pMissEntryPoint                 Entry point name of the miss shader
 * \param[in]  pMissSpecializationInfo         Specialization of the miss shader, or NULL
 * \param[in]  pClosestHitShaderModuleNext     Optional extension chain for the closest hit VkShaderModuleCreateInfo, or NULL
 * \param[in]  closestHitCodeSize              Size in bytes of the closest hit shader code
 * \param[in]  pClosestHitCode                 Closest hit shader SPIR-V code
 * \param[in]  pClosestHitStageNext            Optional extension chain for the closest hit VkPipelineShaderStageCreateInfo, or NULL
 * \param[in]  pClosestHitEntryPoint           Entry point name of the closest hit shader
 * \param[in]  pClosestHitSpecializationInfo   Specialization of the closest hit shader, or NULL
 * \param[in]  pAllocator                      Optional allocation callbacks, or NULL
 * \param[out] pRaygenShaderModule             Receives the created raygen shader module; the caller destroys it, at the earliest once the pipeline exists
 * \param[out] pMissShaderModule               Receives the created miss shader module; the caller destroys it, at the earliest once the pipeline exists
 * \param[out] pClosestHitShaderModule         Receives the created closest hit shader module; the caller destroys it, at the earliest once the pipeline exists
 * \param[out] pPipelineLayout                 A pointer to a VkPipelineLayout handle in which the resulting pipeline layout object is returned
 * \param[out] pPipeline                       Receives the created VkPipeline
 *
 * \retval     VK_SUCCESS   Command successfully completed.
 */
